def doc(n, title, text, url, typ, published, available, basis, time_url, status, note, revised=None):
    suffix = '.xml' if n in {4,5,7,10} else ('.pdf' if n == 11 else '.html')
    filename = f'natural_001_doc_{n:03d}{suffix}'
    raw = RAW / filename
    return {
        'document_id': f'natural_001_doc_{n:03d}', 'title': title, 'text': text,
        'text_status': 'verbatim_or_source_grounded_extract', 'source_url': url,
        'canonical_url': url, 'source_type': typ, 'original_published_at': published,
        'available_at': available, 'revised_at': revised, 'vendor_indexed_at': None,
        'timestamp_timezone_basis': basis, 'timestamp_source_url': time_url,
        'retrieved_at': retrieved.get(filename), 'archive_path': f'raw/natural_001/{filename}',
        'content_sha256': hashlib.sha256(raw.read_bytes()).hexdigest(),
        'license_or_use_note': ('Public SEC-hosted issuer filing; no separate license identified; retained only as a research snapshot.' if typ.startswith('SEC_') else 'Copyrighted/public web source; no open-content license verified. Retained only as a research snapshot and not for redistribution.'),
        'source_verification_status': status, 'verified_by': 'data_line_initial_verification_2026-08-07',
        'verification_note': note + ' vendor_indexed_at is null because no third-party vendor copy or vendor-index timestamp was used.'
    }

